{
  "results": [
    {
      "server": "headroom",
      "tools": [
        {
          "tool_name": "headroom__headroom_compress",
          "description": "Compress content to save context window space. Use this on large tool outputs, file contents, search results, or any content you want to shrink before reasoning over it. The original is stored and can be retrieved later via mcp__headroom__headroom_retrieve. Returns compressed text + a hash for retrieval.",
          "score": 4.300911903381348,
          "input_schema": {
            "type": "object",
            "properties": {
              "content": {
                "type": "string",
                "description": "The content to compress. Can be any text: file contents, JSON, search results, logs, code, etc."
              }
            },
            "required": [
              "content"
            ]
          }
        }
      ]
    },
    {
      "server": "resend",
      "tools": [
        {
          "tool_name": "resend__list-contact-imports",
          "description": "List contact imports from Resend. Optionally filter by status. Use to discover import IDs or review past imports.",
          "score": 3.540910243988037,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "limit": {
                "description": "Number of contact imports to retrieve. Default: 10, Max: 100, Min: 1",
                "type": "number",
                "minimum": 1,
                "maximum": 100
              },
              "after": {
                "description": "Contact import ID after which to retrieve more (for forward pagination). Cannot be used with \"before\".",
                "type": "string"
              },
              "before": {
                "description": "Contact import ID before which to retrieve more (for backward pagination). Cannot be used with \"after\".",
                "type": "string"
              },
              "status": {
                "description": "Filter imports by status.",
                "type": "string",
                "enum": [
                  "queued",
                  "in_progress",
                  "completed",
                  "failed"
                ]
              }
            }
          }
        },
        {
          "tool_name": "resend__get-automation-runs",
          "description": "**Purpose:** List runs for an automation, or get details of a specific run.\n\n**Modes:**\n- With `runId`: Returns detailed run info with step-by-step execution status, outputs, and errors.\n- Without `runId`: Lists runs for the automation with optional status filter.\n\n**When to use:**\n- User wants to see if an automation is working\n- User wants to debug a failed automation run\n- User asks \"why did this automation fail?\" or \"show me recent runs\"\n\n**Run statuses:** running, completed, failed, cancelled\n**Step statuses:** pending, running, completed, failed, skipped, waiting",
          "score": 3.4988911151885986,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "automationId": {
                "type": "string",
                "minLength": 1,
                "description": "The automation ID or Resend dashboard URL (e.g. https://resend.com/automations/<id>)"
              },
              "runId": {
                "description": "Specific run ID to get details for. If omitted, lists all runs.",
                "type": "string"
              },
              "status": {
                "description": "Filter runs by status (for list mode only).",
                "type": "string",
                "enum": [
                  "running",
                  "completed",
                  "failed",
                  "cancelled"
                ]
              },
              "limit": {
                "description": "Number of runs to retrieve (for list mode).",
                "type": "number",
                "minimum": 1,
                "maximum": 100
              },
              "after": {
                "description": "Cursor for forward pagination (for list mode).",
                "type": "string"
              },
              "before": {
                "description": "Cursor for backward pagination (for list mode).",
                "type": "string"
              }
            },
            "required": [
              "automationId"
            ]
          }
        }
      ]
    },
    {
      "server": "github",
      "tools": [
        {
          "tool_name": "github__get_copilot_space",
          "description": "This tool can be used to provide additional context to the chat from a specific Copilot space. If the user mentions the keyword 'Copilot space' with the name and owner of the space, execute this tool.\n\nThe response includes a table of contents (TOC) listing all documents in the space, followed by the full content of each document. Documents are separated by markers in the format: '--- Document N: path (size) ---'. When searching for specific information, use grep (or equivalent command) to search across all documents; the separator lines will help identify which document contains the matching content.",
          "score": 3.453887462615967,
          "input_schema": {
            "type": "object",
            "properties": {
              "name": {
                "type": "string",
                "description": "The name of the space"
              },
              "owner": {
                "type": "string",
                "description": "The owner of the space",
                "x-mcp-header": "owner"
              }
            },
            "required": [
              "owner",
              "name"
            ]
          }
        }
      ]
    },
    {
      "server": "mediawiki-mcp-server",
      "tools": [
        {
          "tool_name": "mediawiki-mcp-server__oauth-status",
          "description": "Lists wikis with stored OAuth tokens, their scopes, and expiry. Stdio only. Never returns token values.",
          "score": 3.314755439758301,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {}
          }
        }
      ]
    }
  ],
  "total_hidden_tools": 261,
  "status": "ready",
  "note": null
}
